        return
    it=iter(data)
    n=next(it); m=next(it)
    cons=[[] for _ in range(n)]
    for _ in range(m):
        l=next(it)-1; r=next(it)-1; x=next(it)-1
        cons[x].append((l,r))

    inf=n+1
    threshold=[[inf]*n for _ in range(n)]
    for k in range(n):
        exact=[inf]*n
        for l,r in cons[k]:
            if r<exact[l]:
                exact[l]=r
        cur=inf
        for l in range(n-1,-1,-1):
            if exact[l]<cur:
                cur=exact[l]
            threshold[k][l]=cur

    choose=[[0]*(n+1) for _ in range(n+1)]
    for a in range(n+1):
        choose[a][0]=choose[a][a]=1
        for b in range(1,a):
            choose[a][b]=(choose[a-1][b-1]+choose[a-1][b])%MOD

    dp=[[0]*n for _ in range(n)]
    for length in range(1,n+1):
        for l in range(n-length+1):
            r=l+length-1
            total=0
            for k in range(l,r+1):
                # A constrained interval with maximum k is necessarily violated
