    out = {}
    while d * d <= x:
        if x % d == 0:
            c = 0
            while x % d == 0:
                x //= d
                c += 1
            out[d] = c
        d += 1
    if x > 1:
        out[x] = 1
    return out

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = [factor(x) for x in data[1:]]
    ans = 1

    for p in set(q for f in factors for q in f):
        vals = [f.get(p, 0) for f in factors]
        limit = sum(vals)
        powers = [pow(p, h, MOD) for h in range(limit + 1)]

        # a: paths not yet visiting height zero; b: paths that have visited it.
        a = [0] * (limit + 1)
        b = [0] * (limit + 1)
        b[0] = 1
        for h in range(1, limit + 1):
            a[h] = powers[h]

        for step in vals:
            na = [0] * (limit + 1)
            nb = [0] * (limit + 1)
            for h in range(limit + 1):
                x, y = a[h], b[h]
                if not x and not y:
                    continue
                targets = (h,) if step == 0 else (h + step, h - step)
                for nh in targets:
                    if 0 <= nh <= limit:
                        w = powers[nh]
                        if nh == 0:
                            nb[0] = (nb[0] + (x + y) * w) % MOD
                        else:
                            na[nh] = (na[nh] + x * w) % MOD
                            nb[nh] = (nb[nh] + y * w) % MOD
            a, b = na, nb
        ans = ans * sum(b) % MOD

    print(ans)

