def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for k in range(p, mx + 1, p):
                phi[k] -= phi[k] // p

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for k in range(p * p, mx + 1, p):
                if spf[k] == k:
                    spf[k] = p

    divisor_cache = {}

    def get_divisors(x):
        cached = divisor_cache.get(x)
        if cached is not None:
            return cached
        t = x
        factors = []
        while t > 1:
            p = spf[t]
            e = 0
            while t % p == 0:
                t //= p
                e += 1
            factors.append((p, e))
        ds = [1]
        for p, e in factors:
            old = ds
            ds = old.copy()
            mul = 1
            for _ in range(e):
                mul *= p
                ds.extend(d * mul for d in old)
        divisor_cache[x] = ds
        return ds

    sums = [0] * (mx + 1)
    ans = 0
    weight = 1
    output = []
    for x in a:
        ds = get_divisors(x)
        add = 0
        for d in ds:
            add += phi[d] * sums[d]
        ans = (2 * ans + add) % MOD
        output.append(str(ans))
        for d in ds:
            value = sums[d] + weight
            if value >= MOD:
                value -= MOD
            sums[d] = value
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

