from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, i))

        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, i in at[r]:
                heapq.heappush(heap, (-a, i))

            if not heap:
                base += r
                continue

            top = -heap[0][0]
            base += r - top

            # In a min-heap, the second-smallest element is the smaller
            # of the root's children (or the only child if there is one).
            second = max((-heap[j][0] for j in (1, 2) if j < len(heap)), default=0)
            if top > second:
                gains[heap[0][1]] += top - second

        return base + max(gains, default=0)

