import sys
input = sys.stdin.readline

N, M, Q = map(int, input().split())
edges = [None] * M
for i in range(M):
    a, b, c = map(int, input().split())
    edges[i] = (a - 1, b - 1, c)

queries = []
closed = [False] * M
for _ in range(Q):
    q = list(map(int, input().split()))
    if q[0] == 1:
        i = q[1] - 1
        closed[i] = True
        queries.append((1, i))
    else:
        queries.append((2, q[1] - 1, q[2] - 1))

INF = 10**30
dist = [[INF] * N for _ in range(N)]
for i in range(N):
    dist[i][i] = 0
for i, (a, b, c) in enumerate(edges):
    if not closed[i]:
        dist[a][b] = dist[b][a] = c

# APSP in the graph remaining after all closures.
for k in range(N):
    row_k = dist[k]
    for i in range(N):
        dik = dist[i][k]
        if dik == INF:
            continue
        row_i = dist[i]
        for j in range(N):
            candidate = dik + row_k[j]
            if candidate < row_i[j]:
                row_i[j] = candidate

answers = []
for q in reversed(queries):
    if q[0] == 2:
        value = dist[q[1]][q[2]]
        answers.append(str(-1 if value == INF else value))
    else:
        a, b, w = edges[q[1]]
        # Snapshot the old distances to the endpoints so the new edge is
        # used at most once in each candidate path.
        to_a = [dist[i][a] for i in range(N)]
        to_b = [dist[i][b] for i in range(N)]
        for i in range(N):
            row = dist[i]
            via_a = to_a[i] + w
            via_b = to_b[i] + w
            for j in range(N):
                candidate = via_a + to_b[j]
                if candidate < row[j]:
                    row[j] = candidate
                candidate = via_b + to_a[j]
                if candidate < row[j]:
                    row[j] = candidate

print('\n'.join(reversed(answers)))

