import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    idx = 2
    for _ in range(n):
        a, p, b, q = data[idx:idx + 4]
        idx += 4
        g = gcd(a, b)
        if p * b <= q * a:
            # S is at least as cost-effective; enumerate the number of T machines.
            processes.append((a, p, b, q, a // g, True))
        else:
            # T is more cost-effective; enumerate the number of S machines.
            processes.append((a, p, b, q, b // g, False))

    def feasible(capacity):
        total = 0
        for a, p, b, q, limit, enumerate_t in processes:
            best = 10**30
            if enumerate_t:
                for y in range(limit):
                    remaining = capacity - b * y
                    x = 0 if remaining <= 0 else (remaining + a - 1) // a
                    best = min(best, y * q + x * p)
            else:
                for x in range(limit):
                    remaining = capacity - a * x
                    y = 0 if remaining <= 0 else (remaining + b - 1) // b
                    best = min(best, x * p + y * q)
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

