MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        m = len(s)

        fact = [1] * (m + 1)
        for i in range(1, m + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (m + 1)
        inv_fact[m] = pow(fact[m], MOD - 2, MOD)
        for i in range(m, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def choose(n, r):
            return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

        good = []
        for t in range(1, m + 1):
            value = t
            steps = 0
            while value > 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                good.append(t)

        answer = 0
        for t in good:
            ways = 0
            ones = 0
            for i, bit in enumerate(s):
                if bit == '1':
                    remaining = m - i - 1
                    need = t - ones
                    if 0 <= need <= remaining:
                        ways = (ways + choose(remaining, need)) % MOD
                    ones += 1
            answer = (answer + ways) % MOD
        return answer

