    def countKReducibleNumbers(self, s: str, k: int) -> int:
        m=len(s)
        # reductions needed from t to 1
        good=[]
        for t in range(1,m+1):
            y=t
            steps=0
            while y>1:
                y=y.bit_count()
                steps+=1
            if steps<=k-1:
                good.append(t)
        ans=0
        for t in good:
            ways=0
            ones=0
            for i,ch in enumerate(s):
                if ch=='1':
                    rem=m-i-1
                    need=t-ones
                    if 0<=need<=rem:
                        ways+=comb(rem,need)
