from collections import deque
import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]
    size = n * n
    dist = [[-1] * size for _ in range(2)]
    queues = [deque(), deque()]
    counts = [0, 0]

    # Empty string centers (even lengths) and one-edge centers (odd lengths).
    for i in range(n):
        k = i * n + i
        dist[0][k] = 0
        queues[0].append(k)
        counts[0] += 1
        for j, c in enumerate(g[i]):
            if c != '-':
                k = i * n + j
                if dist[1][k] < 0:
                    dist[1][k] = 1
                    queues[1].append(k)
                    counts[1] += 1

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for u in range(n):
        for v, c in enumerate(g[u]):
            if c != '-':
                z = ord(c) - 97
                outgoing[u][z].append(v)
                incoming[v][z].append(u)

    for parity in range(2):
        q = queues[parity]
        while q and counts[parity] < size:
            k = q.popleft()
            a, b = divmod(k, n)
            nd = dist[parity][k] + 2
            for z in range(26):
                ins = incoming[a][z]
                outs = outgoing[b][z]
                if ins and outs:
                    for u in ins:
                        base = u * n
                        for v in outs:
                            t = base + v
                            if dist[parity][t] < 0:
                                dist[parity][t] = nd
                                q.append(t)
                                counts[parity] += 1

    result = []
    for i in range(n):
        row = []
        for j in range(n):
            even = dist[0][i * n + j]
            odd = dist[1][i * n + j]
            if even < 0:
                row.append(str(odd))
            elif odd < 0:
                row.append(str(even))
            else:
                row.append(str(min(even, odd)))
        result.append(' '.join(row))
    print('\n'.join(result))

main()

