import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    upper_teeth = vals[::2]
    lower_teeth = vals[1::2]
    pair_sums = [u + d for u, d in zip(upper_teeth, lower_teeth)]

    def feasible(h):
        lo = max(0, h - lower_teeth[0])
        hi = min(upper_teeth[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            next_lo = max(0, h - lower_teeth[i])
            next_hi = min(upper_teeth[i], h)
            lo = max(next_lo, lo - x)
            hi = min(next_hi, hi + x)
            if lo > hi:
                return False
        return True

    left, right = 0, min(pair_sums)
    while left < right:
        mid = (left + right + 1) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid - 1

    print(sum(pair_sums) - n * left)

if __name__ == '__main__':
    main()

