    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue
    q = N // d
    # Solve 3y^2 + 3dy + d^2 = q using its discriminant.
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s != disc:
        continue
    numerator = s - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        print(y + d, y)
        break
