from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        fact = [math.factorial(i) for i in range(n + 1)]

        result = []
        previous = None

        for _ in range(n):
            chosen = None
            for x in sorted(odds + evens):
                if previous is not None and x % 2 == previous % 2:
                    continue

                remaining_odds = len(odds) - (x % 2 == 1)
                remaining_evens = len(evens) - (x % 2 == 0)
                remaining = remaining_odds + remaining_evens

                # The next required parity is opposite to x's parity.
                start_parity = 1 - (x % 2)  # odd = 1, even = 0
                start_count = (remaining + 1) // 2
                other_count = remaining // 2

                if start_parity == 1:
                    valid = (remaining_odds == start_count and
                             remaining_evens == other_count)
                else:
                    valid = (remaining_evens == start_count and
                             remaining_odds == other_count)

                count = (fact[remaining_odds] * fact[remaining_evens]
                         if valid else 0)

                if k > count:
                    k -= count
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            result.append(chosen)
            if chosen % 2:
                odds.remove(chosen)
            else:
                evens.remove(chosen)
            previous = chosen

        return result

