class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half_len = (n + 1) // 2

        # Powers of 10 give each decimal position's contribution modulo k.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        weights = [0] * half_len
        for i in range(half_len):
            j = n - 1 - i
            weights[i] = (powers[i] + (powers[j] if j != i else 0)) % k

        # suffix[i][r] indicates whether positions i onward can contribute r mod k.
        suffix = [None] * (half_len + 1)
        suffix[half_len] = bytearray([1] + [0] * (k - 1))
        for i in range(half_len - 1, -1, -1):
            following = suffix[i + 1]
            possible = bytearray(k)
            weight = weights[i]
            for residue in range(k):
                for digit in range(10):
                    if following[(residue - digit * weight) % k]:
                        possible[residue] = 1
                        break
            suffix[i] = possible

        chosen = []
        prefix_residue = 0
        for i, weight in enumerate(weights):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                needed = (-(prefix_residue + digit * weight)) % k
                if suffix[i + 1][needed]:
                    chosen.append(str(digit))
                    prefix_residue = (prefix_residue + digit * weight) % k
                    break

        first_half = ''.join(chosen)
        if n % 2:
            return first_half + first_half[:-1][::-1]
        return first_half + first_half[::-1]

