from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # next strictly greater element; these positions partition the
        # prefix-maximum values starting at each index into constant blocks.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        jump = [nxt] + [[n] * n for _ in range(levels - 1)]
        sums = [[0] * n for _ in range(levels)]
        for i in range(n):
            sums[0][i] = (nxt[i] - i) * nums[i]
        for j in range(1, levels):
            prev_jump, cur_jump = jump[j - 1], jump[j]
            prev_sum, cur_sum = sums[j - 1], sums[j]
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    cur_jump[i] = prev_jump[mid]
                    cur_sum[i] = prev_sum[i] + prev_sum[mid]
                else:
                    cur_jump[i] = n
                    cur_sum[i] = prev_sum[i]

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def cost(left: int, right: int) -> int:
            # Sum of prefix maxima minus the original element sum.
            cur = left
            raised_sum = 0
            bound = right + 1
            for j in range(levels - 1, -1, -1):
                if cur < n and jump[j][cur] <= bound:
                    raised_sum += sums[j][cur]
                    cur = jump[j][cur]
            if cur <= right:
                raised_sum += (right - cur + 1) * nums[cur]
            return raised_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        right = 0
        for left in range(n):
            if right < left:
                right = left
            while right < n and cost(left, right) <= k:
                right += 1
            answer += right - left
        return answer

