from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        parent[0] = 0
        for u in order:
            for v, _ in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        dp_out = [0] * n
        dp_in = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp_out[v]
                    gains.append(w + dp_in[v] - dp_out[v])
            gains.sort(reverse=True)
            dp_out[u] = base + sum(g for g in gains[:k] if g > 0)
            dp_in[u] = base + sum(g for g in gains[:k - 1] if g > 0)
        return dp_out[0]

