from functools import lru_cache

@lru_cache(None)
def winning(takahashi, aoki, turn):
    hand = takahashi if turn == 0 else aoki
    if hand == 0:
        return False

    table = full ^ (takahashi | aoki)
    cards = hand
    while cards:
        played_bit = cards & -cards
        cards -= played_bit
        played = played_bit.bit_length() - 1
        updated_t = takahashi ^ played_bit if turn == 0 else takahashi
        updated_a = aoki ^ played_bit if turn == 1 else aoki

        # Play without taking a card.
        if turn == 0:
            if not winning(updated_t, updated_a, 1):
                return True
        else:
            if not winning(updated_t, updated_a, 0):
                return True

        # Or take any table card whose number is strictly smaller.
        candidates = table
        while candidates:
            taken_bit = candidates & -candidates
            candidates -= taken_bit
            taken = taken_bit.bit_length() - 1
            if card_values[taken] < card_values[played]:
                if turn == 0:
                    if not winning(updated_t | taken_bit, updated_a, 1):
                        return True
                else:
                    if not winning(updated_t, updated_a | taken_bit, 0):
                        return True
    return False

print('Takahashi' if winning(initial_t, initial_a, 0) else 'Aoki')

