from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Produce the postorder string iteratively, and record each node's
        # position and subtree size in that string.
        order = []
        stack = [(0, False)]
        sizes = [1] * n
        pos = [0] * n
        while stack:
            x, done = stack.pop()
            if done:
                pos[x] = len(order)
                order.append(s[x])
                if x:
                    sizes[parent[x]] += sizes[x]
            else:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))

        t = ''.join(order)

        # Manacher radii for odd- and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and t[i - k] == t[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and t[i - k - 1] == t[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            length = sizes[x]
            start = pos[x] - length + 1
            if length % 2:
                center = (start + pos[x]) // 2
                answer[x] = odd[center] >= length // 2 + 1
            else:
                center = (start + pos[x] + 1) // 2
                answer[x] = even[center] >= length // 2
        return answer

