from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix sums at indices with the same remainder modulo k
        # differ by a length divisible by k.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        answer = None

        for i, value in enumerate(nums, 1):
            prefix += value
            remainder = i % k
            previous_min = min_prefix[remainder]

            if previous_min is not None:
                candidate = prefix - previous_min
                if answer is None or candidate > answer:
                    answer = candidate
                if prefix < previous_min:
                    min_prefix[remainder] = prefix
            else:
                min_prefix[remainder] = prefix

        return answer

