class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        for _ in range(t):
            nxt = [0] * 26
            for i in range(25):
                nxt[i + 1] = counts[i]
            nxt[0] = counts[25]
            nxt[1] = (nxt[1] + counts[25]) % MOD
            counts = nxt

        return sum(counts) % MOD

