class Solution:
    def countPairs(self, nums: List[int]) -> int:
        width = max(len(str(x)) for x in nums)
        seen = {}
        answer = 0

        for x in nums:
            s = str(x).zfill(width)
            variants = {s}
            digits = list(s)
            for i in range(width):
                for j in range(i + 1, width):
                    digits[i], digits[j] = digits[j], digits[i]
                    variants.add(''.join(digits))
                    digits[i], digits[j] = digits[j], digits[i]

            answer += sum(seen.get(v, 0) for v in variants)
