from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)

        for outlier in sorted(nums, reverse=True):
            remainder = total - outlier
            if remainder % 2 != 0:
                continue
            sum_value = remainder // 2
            needed = 2 if sum_value == outlier else 1
            if counts[sum_value] >= needed:
                return outlier

        # The input guarantees that a potential outlier exists.
        return 0

