import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        is_prime = [True] * 10000
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for x in range(p * p, 10000, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        digits = len(str(n))
        places = [10 ** i for i in range(digits)]
        leading_place = 10 ** (digits - 1)

        # Dijkstra: entering a number adds that number to the path cost.
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for place in places:
                digit = (x // place) % 10
                for new_digit in (digit - 1, digit + 1):
                    if not 0 <= new_digit <= 9:
                        continue
                    if place == leading_place and new_digit == 0:
                        continue
                    y = x + (new_digit - digit) * place
                    if is_prime[y]:
                        continue
                    new_cost = cost + y
                    if new_cost < dist.get(y, float('inf')):
                        dist[y] = new_cost
                        heapq.heappush(pq, (new_cost, y))

        return -1

