from typing import List
class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        z0 = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z0[i] = min(right - i + 1, z0[i - left])
            while i + z0[i] < n and nums[z0[i]] == nums[i + z0[i]]:
                z0[i] += 1
            if i + z0[i] - 1 > right:
                left, right = i, i + z0[i] - 1
        ans = 0
        for i in range(1, n - 1):
            first_ok = z0[i] >= i
            first_j = 2 * i
            if first_ok and first_j <= n - 1:
                ans += n - first_j
            m = n - i
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k <= right:
                    z[k] = min(right - k + 1, z[k - left])
                while k + z[k] < m and nums[i + z[k]] == nums[i + k + z[k]]:
                    z[k] += 1
                if k + z[k] - 1 > right:
                    left, right = k, k + z[k] - 1
            for k in range(1, m // 2 + 1):
                if z[k] >= k and not (first_ok and k >= i):
                    ans += 1
        return ans

