import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse reversed edges from 0. best[v] is the least possible
        # maximum edge weight on a directed path from v to 0.
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        inf = 10**18
        best = [inf] * n
        best[0] = 0
        heap = [(0, 0)]
        while heap:
            cost, v = heapq.heappop(heap)
            if cost != best[v]:
                continue
            for u, weight in rev[v]:
                candidate = max(cost, weight)
                if candidate < best[u]:
                    best[u] = candidate
                    heapq.heappush(heap, (candidate, u))

        if any(value == inf for value in best):
            return -1
        # Since threshold >= 1, a spanning tree directed toward 0 satisfies
        # the outgoing-edge bound whenever all nodes can reach 0.
        return max(best)

