class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        start = 0
        for i in range(1, len(t) + 1):
            if i == len(t) or t[i] != t[start]:
                runs.append((t[start], i - start))
                start = i
        base = s.count('1')
        # Eligible 1-runs are those strictly between zero runs.
        eligible = [i for i, (ch, _) in enumerate(runs)
                    if ch == '1' and i > 0 and i + 1 < len(runs)]
        best = base
        zero_runs = [(i, length) for i, (ch, length) in enumerate(runs) if ch == '0']
        # Trade where the second flip uses the newly merged zero block.
        for i in eligible:
            best = max(best, base + runs[i - 1][1] + runs[i + 1][1])
        # Or use a separate zero run that is not adjacent to the removed one-run.
        top = sorted(zero_runs, key=lambda p: p[1], reverse=True)[:3]
        for i in eligible:
            adjacent = {i - 1, i + 1}
            for zi, zl in top:
                if zi not in adjacent:
                    best = max(best, base + zl - runs[i][1])
                    break
        return best

